-- MoP Classic: Pandaren (races 24/25/26) and Monk (class 10) character creation.
-- Generated by tools/mop-content/gen_pandaren_monk_create.ts; do not edit by hand. Race/class pairs: client CharBaseInfo.db2.
-- Sources: ref_master = TrinityCore master TDB, ref_sfdb = SkyFire 5.4.8 world DB (+ core updates), world = cata_classic TDB.

-- world_safe_locs: ref_master.world_safe_locs ID 3295
DELETE FROM `world_safe_locs` WHERE `ID`=3295;

-- race_unlock_requirement: ref_master.race_unlock_requirement raceID 24-26
DELETE FROM `race_unlock_requirement` WHERE `raceID` IN (24,25,26);

-- class_expansion_requirement: ref_master.class_expansion_requirement for each CharBaseInfo pair (Monk needs expansion 4)
DELETE FROM `class_expansion_requirement` WHERE `ClassID`=10 OR `RaceID` IN (24,25,26);

-- player_racestats: ref_sfdb.player_levelstats race 24 minus race 1 at levels 86-90 (30 rows agree)
DELETE FROM `player_racestats` WHERE `race` IN (24,25,26);

-- player_classlevelstats: Monk = ref_sfdb.player_levelstats race 1 class 10 (Human modifiers are 0), levels 1-90
-- TODO(verify): SkyFire's Monk curve copies Warrior up to 80; check against MoP base stats before levelling past 10.
DELETE FROM `player_classlevelstats` WHERE `class`=10;

-- playercreateinfo: CharBaseInfo pairs only (drops 24:9, 25:6, 25:9, 26:6, 26:9); new pairs copy the race's world Warrior position
DELETE FROM `playercreateinfo` WHERE `class`=10 OR `race` IN (24,25,26);

-- playercreateinfo_action: ref_sfdb.playercreateinfo_action (spells checked against SpellName.db2)
DELETE FROM `playercreateinfo_action` WHERE `class`=10 OR `race` IN (24,25,26);

-- playercreateinfo_cast_spell: Pandaren rows from ref_master (Mage/Warlock row limited to Mage), hunter pet from ref_sfdb,
-- Gnome/Troll Monk rows for the race auras cata_classic only casts on pre-Monk class masks. Spells checked against SpellName.db2.
DELETE FROM `playercreateinfo_cast_spell` WHERE `raceMask`=8388608 OR (`classMask`=512 AND `spell` IN (80653,71033));
